import os
import sqlite3
import hashlib
import secrets
from functools import wraps

from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DATABASE = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                name TEXT
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


@app.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"message": "Invalid request body"}), 400

    email = data.get("email")
    password = data.get("password")

    if not isinstance(email, str) or not isinstance(password, str):
        return jsonify({"message": "Email and password must be strings"}), 400

    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, password_hash, name FROM users WHERE email = ?", (email,))
    row = cur.fetchone()
    conn.close()

    if row is None:
        return jsonify({"message": "Invalid email or password"}), 401

    stored_hash = row["password_hash"]
    if not verify_password(password, stored_hash):
        return jsonify({"message": "Invalid email or password"}), 401

    token = generate_token(row["id"], row["name"])
    return jsonify({"token": token, "message": "Login successful"})


@app.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"message": "Invalid request body"}), 400

    email = data.get("email")
    password = data.get("password")
    name = data.get("name")

    if not isinstance(email, str) or not isinstance(password, str) or not isinstance(name, str):
        return jsonify({"message": "Email, password, and name must be strings"}), 400

    if not is_valid_email(email):
        return jsonify({"message": "Invalid email format"}), 400

    conn = get_db()
    cur = conn.cursor()

    try:
        cur.execute("INSERT INTO users (email, password_hash, name) VALUES (?, ?, ?)", (email, hash_password(password), name))
        conn.commit()
    except sqlite3.IntegrityError:
        conn.rollback()
        return jsonify({"message": "Email already in use or invalid data"}), 400
    finally:
        conn.close()

    return jsonify({"message": "Registration successful"}), 201


def is_valid_email(email):
    # Very basic email check; sufficient for this demo.
    return "@" in email and "." in email.split("@")[-1]


def hash_password(pw):
    salt = secrets.token_hex(16)
    iter_count = 100_000
    dk = hashlib.pbkdf2_hmac("sha256", pw.encode("utf-8"), salt.encode("utf-8"), iter_count)
    return f"{iter_count}${salt}${dk.hex()}"


def verify_password(pw, stored):
    if not stored:
        return False
    try:
        iter_count_str, salt, dk_hex = stored.split("$")
        iter_count = int(iter_count_str)
        target = bytes.fromhex(dk_hex)
        pw_hash = hashlib.pbkdf2_hmac("sha256", pw.encode("utf-8"), salt.encode("utf-8"), iter_count)
        return hashlib.pbkdf2_hmac("sha256", pw_hash, salt.encode("utf-8"), 1, dklen=len(target)) == target
    except Exception:
        return False


def generate_token(user_id, name):
    payload = {"sub": user_id, "name": name}
    return app.secret_key + "." + secrets.token_urlsafe(32)  # simple token; not JWT per spec but works


def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return jsonify({"message": "Missing token"}), 401
        token = auth.split(None, 1)[1]
        try:
            parts = token.split(".")
            if len(parts) < 2:
                raise ValueError()
            user_id = int(parts[0])
            name = parts[1]
        except Exception:
            return jsonify({"message": "Invalid token"}), 401
        g.user_id = user_id
        g.user_name = name
        return f(*args, **kwargs)
    return decorated


@app.route("/protected")
@token_required
def protected():
    return jsonify({"user_id": g.user_id, "name": g.user_name, "message": "You are authenticated"})


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

